fn vec_len<T>(x: &Vec<T>) -> usize {
    x.len()
}

fn numpy_log10(x: Vec<f32>) -> Vec<f32> {
    // Preallocate the output vector to exactly the required length
    let mut result = Vec::with_capacity(x.len());
    
    // Process each element once, pushing its log10 onto the result
    for value in x {
        result.push(value.log10());
    }
    
    result
}

